mapper.insert:
INSERT INTO app_agent_task (
    task_key, task_type, title, objective, constraints_json, status, risk_level, created_by,
    priority, max_steps, max_retries, max_runtime_seconds, max_tokens, max_cost
) VALUES (
    #{taskKey}, #{taskType}, #{title}, #{objective}, #{constraintsJson}, #{status}, #{riskLevel}, #{createdBy},
    #{priority}, #{maxSteps}, #{maxRetries}, #{maxRuntimeSeconds}, #{maxTokens}, #{maxCost}
)

INSERT INTO app_agent_event (
    task_id, step_id, event_seq, event_type, visibility, summary, payload_json
)
VALUES (
    #{taskId}, #{stepId},
    (
        SELECT COALESCE(MAX(event_seq), 0) + 1
        FROM (
            SELECT event_seq
            FROM app_agent_event
            WHERE task_id = #{taskId}
        ) AS existing_events
    ),
    #{eventType}, #{visibility}, #{summary}, #{payloadJson}
)

INSERT INTO app_agent_plan (
    task_id, plan_version, status, plan_json, input_hash, generated_by
) VALUES (
    #{taskId}, #{planVersion}, #{status}, #{planJson}, #{inputHash}, #{generatedBy}
)

INSERT INTO app_agent_step (
    task_id, plan_id, step_key, step_name, agent_role, step_type, status,
    depends_on_json, tool_name, input_json, max_attempts, risk_level, sort_order
) VALUES (
    #{taskId}, #{planId}, #{stepKey}, #{stepName}, #{agentRole}, #{stepType}, #{status},
    #{dependsOnJson}, #{toolName}, #{inputJson}, #{maxAttempts}, #{riskLevel}, #{sortOrder}
)

mapper.update:
UPDATE app_agent_task
SET risk_level = #{riskLevel}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{taskId}

