UPDATE app_agent_step
SET lease_until = #{leaseUntil}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{stepId} AND status = 'RUNNING' AND lease_owner = #{owner}

mapper.select:
SELECT COUNT(*) FROM app_agent_task t
WHERE t.created_by = #{ownerId}
AND t.status = #{status}

    AND (
        t.task_key LIKE CONCAT('%', #{keyword}, '%')
        OR t.title LIKE CONCAT('%', #{keyword}, '%')
        OR t.objective LIKE CONCAT('%', #{keyword}, '%')
    )

SELECT t.id, t.task_key AS taskKey, t.task_type AS taskType, t.title, t.status, t.risk_level AS riskLevel, t.created_by AS createdBy, t.priority, t.max_steps AS maxSteps, t.max_retries AS maxRetries, t.max_runtime_seconds AS maxRuntimeSeconds, t.max_tokens AS maxTokens, t.max_cost AS maxCost, t.current_step_id AS currentStepId, t.total_steps AS totalSteps, t.completed_steps AS completedSteps, t.retry_count AS retryCount, t.token_usage AS tokenUsage, t.cost_amount AS costAmount, t.artifact_count AS artifactCount, t.started_at AS startedAt, t.finished_at AS finishedAt, COALESCE(t.last_error, '') AS lastError, t.created_at AS createdAt, t.updated_at AS updatedAt FROM app_agent_task t WHERE t.created_by = #{ownerId} AND t.status = #{status}
AND ( t.task_key LIKE CONCAT('%', #{keyword}, '%') OR t.title LIKE CONCAT('%', #{keyword}, '%') OR t.objective LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}
